package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_prepend_TriageGen0Test {

    @Test
    public void testPrepend_ValidHtml_PrependsCorrectly() {
        Element parent = new Element("div", "");
        parent.append("<span>Existing</span>");

        String newHtml = "<p>New</p><b>Bold</b>";
        parent.prepend(newHtml);

        // Expected order: <b>Bold</b>, <p>New</p>, <span>Existing</span>
        // Note: The implementation iterates backwards through fragment nodes and calls prependChild.
        // fragment.childNodes() for "<p>New</p><b>Bold</b>" contains [<p>, <b>]
        // Loop i=1: node=<b>, prependChild(<b>) -> [<b>, <span>Existing</span>]
        // Loop i=0: node=<p>, prependChild(<p>) -> [<p>, <b>, <span>Existing</span>]

        String expectedHtml = "<p>New</p><b>Bold</b><span>Existing</span>";
        Assert.assertEquals(expectedHtml, parent.html());
    }

    @Test
    public void testPrepend_WithTextNode() {
        Element parent = new Element("div", "");
        parent.append("<span>Child</span>");

        String newHtml = "Text";
        parent.prepend(newHtml);

        // fragment.childNodes() contains [Text]
        // Loop i=0: node=Text, prependChild(Text) -> [Text, <span>Child</span>]
        Assert.assertEquals("Text<span>Child</span>", parent.html());
    }

    @Test
    public void testPrepend_EmptyHtml() {
        Element parent = new Element("div", "");
        parent.append("<span>Child</span>");

        parent.prepend("");

        // Parser.parseBodyFragment("") results in empty body
        Assert.assertEquals("<span>Child</span>", parent.html());
    }

    @Test(expected = NullPointerException.class)
    public void testPrepend_NullHtml_ThrowsException() {
        Element parent = new Element("div", "");
        parent.prepend(null);
    }

    @Test
    public void testPrepend_ReturnsThis() {
        Element parent = new Element("div", "");
        Element returned = parent.prepend("<span></span>");
        Assert.assertSame(parent, returned);
    }

    @Test
    public void testPrepend_ComplexStructure() {
        Element parent = new Element("ul", "");
        parent.append("<li>Item 1</li>");

        String newHtml = "<li>Item 0</li><div><p>Nested</p></div>";
        parent.prepend(newHtml);

        // fragment nodes: [<li>Item 0</li>, <div><p>Nested</p></div>]
        // i=1: prepend(div) -> [div, li1]
        // i=0: prepend(li0) -> [li0, div, li1]
        String expected = "<li>Item 0</li><div><p>Nested</p></div><li>Item 1</li>";
        Assert.assertEquals(expected, parent.html());
    }
}
